<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/notifications.php';require_once __DIR__.'/../lib/idempotency.php';
send_cors_headers();$auth=require_auth();$userId=auth_user_id($auth);$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';
if($method==='GET'){$stmt=$db->prepare('SELECT r.*,oi.product_name,oi.image,o.order_number FROM return_requests r JOIN order_items oi ON oi.id=r.order_item_id JOIN orders o ON o.id=r.order_id WHERE r.user_id=:user ORDER BY r.requested_at DESC');$stmt->execute(['user'=>$userId]);json_response(200,['success'=>true,'returns'=>$stmt->fetchAll()]);}
if($method==='POST'){$body=get_json_body();$itemId=(int)($body['order_item_id']??0);$quantity=(int)($body['quantity']??0);$type=trim((string)($body['request_type']??''));$reason=trim((string)($body['reason_code']??''));$description=trim((string)($body['description']??''));if(!in_array($type,['return','replacement'],true)||$quantity<1||mb_strlen($reason)<2||mb_strlen($description)<20||mb_strlen($description)>1200)json_response(422,['success'=>false,'message'=>'Return type, quantity, reason and a detailed description are required.']);$idem=begin_idempotent_request('return.create',['type'=>'customer','id'=>$userId],$body);$db->beginTransaction();try{$stmt=$db->prepare('SELECT oi.*,o.user_id,o.order_number,g.status AS group_status,g.policy_snapshot_json FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN vendor_order_groups g ON g.id=oi.vendor_group_id WHERE oi.id=:item AND o.user_id=:user FOR UPDATE');$stmt->execute(['item'=>$itemId,'user'=>$userId]);$item=$stmt->fetch();if(!$item)json_response(404,['success'=>false,'message'=>'Order item not found.']);if($item['group_status']!=='delivered'&&$item['status']!=='delivered')json_response(409,['success'=>false,'message'=>'A return can be requested only after delivery.']);$open=$db->prepare('SELECT COALESCE(SUM(quantity),0) FROM return_requests WHERE order_item_id=:item AND status NOT IN ("rejected","cancelled")');$open->execute(['item'=>$itemId]);if($quantity>(int)$item['quantity']-(int)$open->fetchColumn())json_response(422,['success'=>false,'message'=>'Requested quantity exceeds the eligible quantity.']);$id=uuid_string();$db->prepare('INSERT INTO return_requests (id,order_id,order_item_id,user_id,vendor_id,request_type,quantity,reason_code,description,status,policy_snapshot_json,requested_at,updated_at) VALUES (:id,:order,:item,:user,:vendor,:type,:qty,:reason,:description,"requested",:policy,UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$id,'order'=>$item['order_id'],'item'=>$itemId,'user'=>$userId,'vendor'=>$item['vendor_id'],'type'=>$type,'qty'=>$quantity,'reason'=>$reason,'description'=>$description,'policy'=>$item['policy_snapshot_json']?:'{}']);create_notification('vendor',$item['vendor_id'],'return_requested','Return request received',"A {$type} request was opened for {$item['product_name']}.",'../returns.php',['return_id'=>$id]);record_status_change('return_request',$id,null,'requested',$description);audit_event('customer.return_requested','return_request',$id,['order_item_id'=>$itemId,'quantity'=>$quantity]);$response=['success'=>true,'message'=>'Request submitted for review.','return_id'=>$id,'status'=>'requested'];finish_idempotent_request((int)$idem['id'],201,$response);$db->commit();json_response(201,$response);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
